List<int> inIter(Node? root) {
  final out = <int>[], st = <Node>[];
  var cur = root;
  while (cur != null || st.isNotEmpty) {
    while (cur != null) {
      st.add(cur);
      cur = cur.left;
    }
    final n = st.removeLast();
    out.add(n.v);
    cur = n.right;
  }
  return out;
