int? kth(Node? root, int k) {
  final st = <Node>[];
  var cur = root;
  while (cur != null || st.isNotEmpty) {
    while (cur != null) {
      st.add(cur);
      cur = cur.left;
    }
    final n = st.removeLast();
    if (--k == 0) return n.v;
    cur = n.right;
  }
  return null;
}

void main() {
